```dart
    String? address; // 'address' can be null
    address = '123 Main St'; // Allowed
    address = null; // Allowed

    // To use a nullable variable, you need to check if it's null first
    if (address != null) {
      print(address.length); // Now it's safe to access .length
    }

    // Using the ?. operator for safe calls
    print(address?.length); // Prints null if address is null, otherwise prints the length
    ```

