    class UserProfile {
      late String name; // 'name' is non-nullable but initialized later
      late String _bio; // Private non-nullable field, initialized later

      void initializeProfile(String fetchedName, String fetchedBio) {
        name = fetchedName; // Initialize 'name'
        _bio = fetchedBio; // Initialize '_bio'
      }

      void displayProfile() {
        // 'name' and '_bio' are guaranteed to be initialized here
        print('Name: $name');
        print('Bio: $_bio');
      }
    }

    void main() {
      UserProfile profile = UserProfile();

      // If you try to access 'name' or '_bio' before initializeProfile,
      // it will throw a LateInitializationError.
      // print(profile.name); // Throws error

      profile.initializeProfile('Bob', 'Software Engineer');
      profile.displayProfile();
    }
